var https = require('https');
var http = require('http');

class ProxyAgent extends https.Agent {
  constructor(proxyUrl) {
    super();
    this.proxy = new URL(proxyUrl);
  }
  createConnection(options, callback) {
    var host = options.host || options.hostname;
    var port = options.port || 443;
    var self = this;

    console.log('Connecting via proxy');
    var proxyReq = http.request({
      hostname: this.proxy.hostname,
      port: this.proxy.port,
      path: host + ':' + port,
      method: 'CONNECT',
      headers: { Host: host + ':' + port }
    });

    proxyReq.on('connect', function(res, socket) {
      console.log('Proxy response:', res.statusCode);
      var tls = require('tls');

      // Create TLSSocket with the right options
      var tlsOptions = Object.assign({
        socket: socket,
        servername: host,
        rejectUnauthorized: false
      }, options.tls || {});

      var tlsSocket = new tls.TLSSocket(socket, tlsOptions);
      tlsSocket.on('secureConnect', function() {
        console.log('TLS secureConnected');
        callback(null, tlsSocket);
      });
      tlsSocket.on('error', function(e) {
        console.error('TLSSocket error:', e.message);
      });
    });

    proxyReq.on('error', function(e) {
      console.error('Proxy request error:', e.message);
    });
    proxyReq.setTimeout(10000, function() { 
      proxyReq.destroy(new Error('Proxy timeout')); 
    });
    proxyReq.end();
  }
}

